create table comparador.tb_caracteristica
(
    tag_caracteristica       varchar(64) not null
        constraint tb_caracteristica_pk
            primary key,
    nome_caracteristica      varchar     not null,
    tipo_caracteristica      varchar,
    un_caracteristica        varchar(32),
    descricao_caracteristica text        not null
);

alter table comparador.tb_caracteristica
    owner to runner_dba;

grant insert, select, update on comparador.tb_caracteristica to runner;

create table comparador.tb_caracteristica_dominio
(
    id_caracteristica_dominio serial,
    tag_caracteristica        varchar(64) not null
        constraint tb_caracteristica_dominio_tb_caracteristica_tag_caracteristica_
            references comparador.tb_caracteristica
            on update cascade on delete cascade,
    caracteristica_dominio    varchar     not null
);

alter table comparador.tb_caracteristica_dominio
    owner to runner_dba;

grant select, usage on sequence comparador.tb_caracteristica_dominio_id_caracteristica_dominio_seq to runner;

grant insert, select, update on comparador.tb_caracteristica_dominio to runner;

create table comparador.tb_categoria
(
    tag_categoria    varchar not null
        primary key,
    categoria        varchar not null
        unique,
    tag_tipo_produto varchar
);

alter table comparador.tb_categoria
    owner to runner_dba;

grant insert, select, update on comparador.tb_categoria to runner;

create table comparador.tb_cupom
(
    id_cupom          serial
        primary key,
    cupom             varchar(32) not null,
    link              varchar(256),
    loja              varchar(256),
    condicoes         varchar(256),
    preco_promocional double precision,
    data_cadastro     date default now(),
    data_expiracao    date,
    id_tenis          integer
);

alter table comparador.tb_cupom
    owner to runner_dba;

grant select, usage on sequence comparador.tb_cupom_id_cupom_seq to runner;

grant insert, select, update on comparador.tb_cupom to runner;

create table comparador.tb_genero
(
    genero     varchar(1),
    peso       double precision,
    tamanho    double precision,
    id_produto integer not null,
    constraint tb_genero_pk
        unique (genero, id_produto)
);

alter table comparador.tb_genero
    owner to runner_dba;

create index tb_genero_genero_index
    on comparador.tb_genero (genero);

grant insert, select, update on comparador.tb_genero to runner;

create table comparador.tb_marca
(
    tag_marca varchar not null
        constraint tb_marca_pk
            primary key,
    marca     varchar not null
);

alter table comparador.tb_marca
    owner to runner_dba;

grant insert, select, update on comparador.tb_marca to runner;

create table comparador.tb_media
(
    id_media   integer default nextval('comparador.tb_media_id_media_seq'::regclass) not null
        primary key,
    id_produto integer,
    media_url  varchar(512),
    media_tipo varchar(16)
);

alter table comparador.tb_media
    owner to runner_dba;

alter sequence comparador.tb_media_id_media_seq owned by comparador.tb_media.id_media;

grant insert, select, update on comparador.tb_media to runner;

create table comparador.tb_produto_caracteristica
(
    id_produto_caracteristica serial,
    id_produto                integer     not null,
    tag_caracteristica        varchar(64) not null
        constraint tb_produto_caracteristica_tb_caracteristica_tag_caracteristica_
            references comparador.tb_caracteristica
            on update restrict on delete restrict,
    caracteristica_dominio    varchar     not null,
    descricao_complementa     text
);

alter table comparador.tb_produto_caracteristica
    owner to runner_dba;

grant select, usage on sequence comparador.tb_produto_caracteristica_id_produto_caracteristica_seq to runner;

grant insert, select, update on comparador.tb_produto_caracteristica to runner;

create table comparador.tb_tenis_backup
(
    id_tenis            integer default nextval('comparador.tb_tenis_id_tenis_seq'::regclass) not null
        constraint tb_tenis_pkey
            primary key,
    tag_marca           varchar,
    modelo              varchar,
    versao              varchar,
    num_versao          integer,
    tag_categoria       varchar,
    nivel_amortecimento integer,
    tamanho_drop        double precision,
    entresola           varchar,
    sistema             varchar,
    indicacao           varchar,
    tipo_tamanho        varchar,
    placa               boolean,
    placa_material      varchar,
    obs                 varchar,
    tag                 varchar,
    cabedal             varchar,
    preco_original      double precision,
    solado              varchar,
    texto               text,
    resumo              varchar(160),
    flexibilidade       varchar,
    tamanhos            varchar,
    super_tenis         boolean default false                                                 not null
);

alter table comparador.tb_tenis_backup
    owner to runner_dba;

alter sequence comparador.tb_tenis_id_tenis_seq owned by comparador.tb_tenis_backup.id_tenis;

grant insert, select, update on comparador.tb_tenis_backup to runner;

create table comparador.tb_tipo_produto
(
    tag_tipo_produto   varchar(64) not null
        constraint tb_tipo_produto_pk
            primary key,
    nome_tipo_produto  varchar     not null,
    sequencia_exibicao integer
);

alter table comparador.tb_tipo_produto
    owner to runner_dba;

create table comparador.tb_caracteristica_compara
(
    tag_tipo_produto   varchar(64) not null
        constraint tb_caracteristica_compara_tb_tipo_produto_id_tipo_produto_fk
            references comparador.tb_tipo_produto,
    tag_caracteristica varchar(64) not null
        constraint tb_caracteristica_compara_tb_caracteristica_id_caracteristica_f
            references comparador.tb_caracteristica,
    sequencia_exibicao integer     not null,
    constraint tb_caracteristica_compara_pk
        primary key (tag_tipo_produto, tag_caracteristica)
);

alter table comparador.tb_caracteristica_compara
    owner to runner_dba;

grant insert, select, update on comparador.tb_caracteristica_compara to runner;

create table comparador.tb_produto
(
    id_produto       serial
        constraint tb_produto_pk
            primary key,
    tag_tipo_produto varchar(64)
        constraint tb_produto_tb_tipo_produto_tag_tipo_produto_fk
            references comparador.tb_tipo_produto
            on update restrict on delete restrict,
    tag_marca        varchar(64)
        constraint tb_produto_tb_marca_tag_marca_fk
            references comparador.tb_marca
            on update restrict on delete restrict,
    nome_produto     varchar                           not null,
    num_versao       integer default 0                 not null,
    versao           varchar,
    resumo           varchar,
    descricao        text,
    data_lancamento  date,
    tag_produto      varchar,
    data_cadastro    date    default CURRENT_TIMESTAMP not null,
    preco_referencia double precision,
    tag_categoria    varchar
);

alter table comparador.tb_produto
    owner to runner_dba;

grant select, usage on sequence comparador.tb_produto_id_produto_seq to runner;

grant insert, select, update on comparador.tb_produto to runner;

grant insert, select, update on comparador.tb_tipo_produto to runner;

create table public.desafio_leads
(
    num_inscricao   integer not null
        constraint desafio_leads_pk
            primary key,
    nome            varchar,
    data_nascimento date,
    email           varchar,
    documento       varchar,
    genero          varchar,
    telefone        varchar,
    celular         varchar,
    endereco        varchar,
    numero          varchar,
    complemento     varchar,
    bairro          varchar,
    cidade          varchar,
    uf              varchar,
    cep             varchar,
    pais            varchar,
    num_pedido      integer,
    id_usuario      integer
);

alter table public.desafio_leads
    owner to runner_dba;

create index desafio_leads_email_index
    on public.desafio_leads (email);

create unique index desafio_leads_id_usuario_uindex
    on public.desafio_leads (id_usuario);

create index desafio_leads_nome_index
    on public.desafio_leads (nome);

grant insert, select, update on public.desafio_leads to runner;

create table public.tb_agrega_eventos
(
    id_agrega_evento     serial
        constraint tb_agrega_eventos_pk
            primary key,
    nome_evento_agregado varchar(256)                                   not null,
    tipo_agregacao       varchar(24)                                    not null,
    tag                  varchar,
    id_tema              integer default 1                              not null,
    divisao              varchar default 'distancia'::character varying not null,
    ordem                integer default 300                            not null
);

alter table public.tb_agrega_eventos
    owner to runner_dba;

grant select, usage on sequence public.tb_agrega_eventos_id_agrega_evento_seq to runner;

create unique index tb_agrega_eventos_id_agrega_evento_uindex
    on public.tb_agrega_eventos (id_agrega_evento);

grant insert, select, update on public.tb_agrega_eventos to runner;

create table public.tb_agregadores
(
    id_agregador        serial
        constraint tb_agregadores_pk
            primary key,
    agregador_nome      varchar(128)                                 not null,
    agregador_tag       varchar(128)                                 not null,
    agregador_descricao text,
    id_agregador_pai    integer
        constraint tb_agregadores_tb_agregadores_id_agregador_fk
            references public.tb_agregadores
            on update set null on delete set null,
    id_tema             integer default 0                            not null,
    agregador_tipo      varchar default 'eventos'::character varying not null,
    ordem               integer default 200                          not null
