            references mercado.grafo_run
            on delete cascade,
    peso_0_1         numeric(3, 2)            default 0.50
        constraint rel_peso_faixa
            check ((peso_0_1 >= (0)::numeric) AND (peso_0_1 <= (1)::numeric)),
