create table public.tb_cron_jobs
(
    id_cron_job                     bigserial
        primary key,
    nome                            varchar(160)                                               not null,
    descricao                       text,
    projeto                         varchar(60)  default 'business'::character varying         not null,
    ambiente                        varchar(40)  default 'prod'::character varying             not null,
    endpoint_url                    text                                                       not null,
    http_method                     varchar(10)  default 'GET'::character varying              not null
        constraint tb_cron_jobs_http_method_chk
            check ((http_method)::text = ANY
                   ((ARRAY ['GET'::character varying, 'POST'::character varying, 'PUT'::character varying, 'PATCH'::character varying, 'DELETE'::character varying])::text[])),
    content_type                    varchar(120) default 'application/json'::character varying not null,
    request_body                    text,
    headers_json                    jsonb        default '{}'::jsonb                           not null,
    auth_mode                       varchar(40)  default 'none'::character varying             not null
        constraint tb_cron_jobs_auth_mode_chk
            check ((auth_mode)::text = ANY
                   ((ARRAY ['none'::character varying, 'bearer'::character varying, 'api_key_header'::character varying, 'api_key_query'::character varying, 'hmac_sha256'::character varying])::text[])),
    secret_ref                      varchar(120),
    interval_minutes                integer      default 60                                    not null
        constraint tb_cron_jobs_interval_chk
            check (interval_minutes >= 1),
    timeout_seconds                 integer      default 30                                    not null
        constraint tb_cron_jobs_timeout_chk
            check ((timeout_seconds >= 1) AND (timeout_seconds <= 120)),
    retry_limit                     integer      default 0                                     not null
        constraint tb_cron_jobs_retry_chk
            check ((retry_limit >= 0) AND (retry_limit <= 3)),
    ativo                           boolean      default true                                  not null,
    executar_em_atraso              boolean      default true                                  not null,
    max_runtime_seconds             integer      default 300                                   not null,
    last_run_at                     timestamp,
    next_run_at                     timestamp    default now()                                 not null,
    last_status                     varchar(40),
    last_http_status                varchar(80),
    last_duration_ms                integer,
    last_error                      text,
    data_criacao                    timestamp    default now()                                 not null,
    data_atualizacao                timestamp    default now()                                 not null,
    id_usuario_criacao              bigint,
    id_usuario_atualizacao          bigint,
    notificacao_novos_itens_destino text
);

alter table public.tb_cron_jobs
    owner to runner_dba;

create index tb_cron_jobs_due_idx
    on public.tb_cron_jobs (ativo, next_run_at);

create index tb_cron_jobs_projeto_idx
    on public.tb_cron_jobs (projeto, ambiente);

