        references public.tb_cron_jobs
            on delete cascade,
    trigger_type         varchar(40) default 'scheduled'::character varying not null,
    attempt              integer     default 1                              not null,
    started_at           timestamp   default now()                          not null,
    finished_at          timestamp,
    duration_ms          integer,
    status               varchar(40) default 'running'::character varying   not null,
    http_status          varchar(80),
    response_preview     text,
    error_message        text,
    endpoint_url         text,
    request_body_preview text,
    created_by           bigint
);

alter table public.tb_cron_job_runs
    owner to runner_dba;

create index tb_cron_job_runs_job_idx
