        constraint tb_foco_event_match_state_status_chk
            check ((status)::text = ANY
                   ((ARRAY ['pending'::character varying, 'processing'::character varying, 'linked'::character varying, 'review'::character varying, 'not_found'::character varying, 'conflict'::character varying, 'dismissed'::character varying, 'error'::character varying])::text[])),
    attempts                 integer     default 0                            not null
        constraint tb_foco_event_match_state_attempts_chk
            check (attempts >= 0),
