create table public.tb_agendas
(
    id_agenda            bigserial
        primary key,
    chave_publica        varchar(64)                                        not null
        constraint tb_agendas_chave_publica_uk
            unique,
    nome                 varchar(160)                                       not null,
    descricao            text,
    id_usuario           integer                                            not null
        references public.tb_usuarios
            on update cascade on delete restrict,
    modo                 varchar(16) default 'manual'::character varying    not null
        constraint tb_agendas_modo_ck
            check ((modo)::text = ANY ((ARRAY ['manual'::character varying, 'dinamica'::character varying])::text[])),
    visao_padrao         varchar(16) default 'futuros'::character varying   not null
        constraint tb_agendas_visao_ck
            check ((visao_padrao)::text = ANY
                   ((ARRAY ['futuros'::character varying, 'resultados'::character varying])::text[])),
    dominio_permitido    varchar(255)                                       not null,
    permitir_subdominios boolean     default false                          not null,
    limite_eventos       integer     default 20                             not null
        constraint tb_agendas_limite_ck
            check ((limite_eventos >= 1) AND (limite_eventos <= 100)),
    ordenacao            varchar(20) default 'data'::character varying      not null
        constraint tb_agendas_ordenacao_ck
            check ((ordenacao)::text = ANY ((ARRAY ['data'::character varying, 'manual'::character varying])::text[])),
    status               varchar(16) default 'rascunho'::character varying  not null
        constraint tb_agendas_status_ck
            check ((status)::text = ANY
                   ((ARRAY ['rascunho'::character varying, 'ativa'::character varying, 'pausada'::character varying, 'arquivada'::character varying])::text[])),
    versao               integer     default 1                              not null,
    criado_por           integer
                                                                            references public.tb_usuarios
                                                                                on update cascade on delete set null,
    atualizado_por       integer
                                                                            references public.tb_usuarios
                                                                                on update cascade on delete set null,
    data_criacao         timestamp   default now()                          not null,
    data_atualizacao     timestamp   default now()                          not null,
    tema_embed           varchar(12) default 'escuro'::character varying    not null
        constraint tb_agendas_tema_embed_ck
            check ((tema_embed)::text = ANY
                   ((ARRAY ['claro'::character varying, 'escuro'::character varying])::text[])),
    cor_card_data        varchar(7)  default '#fab120'::character varying   not null
        constraint tb_agendas_cor_card_data_ck
            check ((cor_card_data)::text ~ '^#[0-9a-fA-F]{6}$'::text),
    fonte_cards          varchar(16) default 'trebuchet'::character varying not null
        constraint tb_agendas_fonte_cards_ck
            check ((fonte_cards)::text = ANY
                   ((ARRAY ['trebuchet'::character varying, 'verdana'::character varying, 'georgia'::character varying, 'tahoma'::character varying, 'monospace'::character varying])::text[])),
    raio_cards           varchar(12) default 'atual'::character varying     not null
        constraint tb_agendas_raio_cards_ck
            check ((raio_cards)::text = ANY
                   ((ARRAY ['atual'::character varying, 'medio'::character varying, 'suave'::character varying, 'reto'::character varying])::text[]))
);

