create table public.tb_paginas_gestao
(
    id_pagina            integer                 not null
        primary key
        references public.tb_paginas
            on update cascade on delete cascade,
    ativo                boolean   default true  not null,
    excluido             boolean   default false not null,
    motivo               text,
    data_alteracao       timestamp default now() not null,
    id_usuario_alteracao integer
                                                 references public.tb_usuarios
                                                     on update cascade on delete set null,
    data_exclusao        timestamp,
    id_usuario_exclusao  integer
                                                 references public.tb_usuarios
                                                     on update cascade on delete set null,
    constraint tb_paginas_gestao_exclusao_ck
        check (((excluido = false) AND (data_exclusao IS NULL)) OR
               ((excluido = true) AND (ativo = false) AND (data_exclusao IS NOT NULL)))
);

alter table public.tb_paginas_gestao
    owner to runner_dba;

create index tb_paginas_gestao_estado_idx
    on public.tb_paginas_gestao (excluido asc, ativo asc, data_alteracao desc);

grant delete, insert, select, update on public.tb_paginas_gestao to runner;

create table public.tb_usuarios_gestao_auditoria
(
    id_auditoria     bigserial
        primary key,
    id_usuario_alvo  integer
                                             references public.tb_usuarios
                                                 on update cascade on delete set null,
    id_pagina_alvo   integer
                                             references public.tb_paginas
                                                 on update cascade on delete set null,
    id_usuario_autor integer
                                             references public.tb_usuarios
                                                 on update cascade on delete set null,
    acao             varchar(64)             not null,
    dados_anteriores jsonb,
    dados_novos      jsonb,
    endereco_ip      varchar(64),
    user_agent       varchar(512),
    data_criacao     timestamp default now() not null
);

alter table public.tb_usuarios_gestao_auditoria
    owner to runner_dba;

grant select, usage on sequence public.tb_usuarios_gestao_auditoria_id_auditoria_seq to runner;

create index tb_usuarios_gestao_auditoria_usuario_idx
    on public.tb_usuarios_gestao_auditoria (id_usuario_alvo asc, data_criacao desc);

create index tb_usuarios_gestao_auditoria_pagina_idx
    on public.tb_usuarios_gestao_auditoria (id_pagina_alvo asc, data_criacao desc);

grant insert, select on public.tb_usuarios_gestao_auditoria to runner;

create table news.tb_weekly_digest_runs
(
    id                 bigserial
        primary key,
    edition            text                                   not null,
    period_start       timestamp with time zone               not null,
    period_end         timestamp with time zone               not null,
    status             text                                   not null
        constraint tb_weekly_digest_runs_status_check
            check (status = ANY
                   (ARRAY ['running'::text, 'no_content'::text, 'generated'::text, 'draft'::text, 'published'::text, 'failed'::text])),
    content_id         integer
                                                              references news.tb_content
                                                                  on delete set null,
    source_ids         jsonb,
    source_hash        text,
    model              text,
    openai_response_id text,
    attempt_count      integer                  default 1     not null,
    error_detail       jsonb,
    started_at         timestamp with time zone default now() not null,
    finished_at        timestamp with time zone,
    is_test            boolean                  default false not null
);

alter table news.tb_weekly_digest_runs
    owner to runner_dba;

create index idx_weekly_digest_runs_status
    on news.tb_weekly_digest_runs (status asc, started_at desc);

create unique index uq_weekly_digest_runs_production_period
    on news.tb_weekly_digest_runs (period_start, period_end)
    where (is_test = false);

create table news.tb_content_audio_jobs
(
    id           bigserial
        primary key,
    content_id   integer                                          not null
        references news.tb_content
            on delete cascade,
    body_hash    varchar(64)                                      not null,
    status       varchar(16) default 'pending'::character varying not null
        constraint tb_content_audio_jobs_status_check
            check ((status)::text = ANY
                   ((ARRAY ['pending'::character varying, 'processing'::character varying, 'done'::character varying, 'failed'::character varying])::text[])),
    attempts     integer     default 0                            not null,
    available_at timestamp   default now()                        not null,
    locked_at    timestamp,
    last_error   text,
    created_at   timestamp   default now()                        not null,
    updated_at   timestamp   default now()                        not null,
    unique (content_id, body_hash)
);

alter table news.tb_content_audio_jobs
    owner to runner_dba;

create index idx_content_audio_jobs_pending
    on news.tb_content_audio_jobs (available_at, id)
    where ((status)::text = 'pending'::text);

create table public.tb_percursos
(
    id_percurso          bigserial
        primary key,
    codigo_publico       uuid                                              not null
        unique,
    nome                 varchar(180)                                      not null,
    cidade               varchar(128),
    estado               varchar(2),
    pais                 varchar(2)  default 'BR'::character varying       not null,
    distancia_nominal_m  integer                                           not null
        constraint tb_percursos_distancia_chk
            check (distancia_nominal_m > 0),
    tipo_percurso        varchar(30) default 'rua'::character varying      not null
        constraint tb_percursos_tipo_chk
            check ((tipo_percurso)::text = ANY
                   ((ARRAY ['rua'::character varying, 'trail'::character varying, 'misto'::character varying])::text[])),
    descricao            text,
    visibilidade         varchar(20) default 'privado'::character varying  not null
        constraint tb_percursos_visibilidade_chk
            check ((visibilidade)::text = ANY
                   ((ARRAY ['privado'::character varying, 'compartilhado'::character varying, 'publico'::character varying])::text[])),
    status               varchar(20) default 'rascunho'::character varying not null
        constraint tb_percursos_status_chk
            check ((status)::text = ANY
                   ((ARRAY ['rascunho'::character varying, 'publicado'::character varying, 'arquivado'::character varying])::text[])),
    id_usuario_criador   bigint                                            not null,
    id_conta_responsavel bigint
        constraint fk_tb_percursos_conta_responsavel
            references public.tb_contas
            on update cascade on delete restrict
        constraint tb_percursos_conta_proprietaria_nn
            check (id_conta_responsavel IS NOT NULL),
    criado_em            timestamp   default now()                         not null,
    atualizado_em        timestamp   default now()                         not null
);

comment on column public.tb_percursos.id_conta_responsavel is 'Conta proprietária do percurso. id_usuario_criador registra somente a autoria original.';

alter table public.tb_percursos
    owner to runner_dba;

grant select, usage on sequence public.tb_percursos_id_percurso_seq to runner;

create index tb_percursos_busca_idx
    on public.tb_percursos (status, estado, cidade, distancia_nominal_m);

create index tb_percursos_conta_idx
    on public.tb_percursos (id_conta_responsavel asc, atualizado_em desc);

create index tb_percursos_criador_idx
    on public.tb_percursos (id_usuario_criador asc, atualizado_em desc);

grant insert, select, update on public.tb_percursos to runner;

create table public.tb_percurso_arquivos
(
    id_percurso_arquivo bigserial
        primary key,
    id_percurso         bigint                  not null
        references public.tb_percursos
            on delete restrict,
    versao              integer                 not null,
    storage_key         varchar(512)            not null,
    geojson_storage_key varchar(512)            not null,
    nome_original       varchar(255)            not null,
    mime_type           varchar(100),
    tamanho_bytes       bigint                  not null
        constraint tb_percurso_arquivos_tamanho_chk
            check (tamanho_bytes > 0),
    sha256              char(64)                not null,
    quantidade_pontos   integer                 not null
        constraint tb_percurso_arquivos_pontos_chk
            check (quantidade_pontos >= 2),
    distancia_gpx_m     numeric(14, 2)          not null,
    elevacao_min_m      numeric(10, 2),
    elevacao_max_m      numeric(10, 2),
    ganho_elevacao_m    numeric(12, 2),
    bbox_min_lat        numeric(10, 7)          not null,
    bbox_min_lng        numeric(10, 7)          not null,
    bbox_max_lat        numeric(10, 7)          not null,
    bbox_max_lng        numeric(10, 7)          not null,
    ativo               boolean   default true  not null,
    id_usuario_criador  bigint                  not null,
    criado_em           timestamp default now() not null,
    constraint tb_percurso_arquivos_versao_uq
        unique (id_percurso, versao)
);

alter table public.tb_percurso_arquivos
    owner to runner_dba;

grant select, usage on sequence public.tb_percurso_arquivos_id_percurso_arquivo_seq to runner;

create index tb_percurso_arquivos_percurso_idx
    on public.tb_percurso_arquivos (id_percurso asc, versao desc);

create index tb_percurso_arquivos_hash_idx
    on public.tb_percurso_arquivos (sha256);

grant insert, select, update on public.tb_percurso_arquivos to runner;

create table public.tb_percurso_historico
(
    id_historico        bigserial
        primary key,
    id_percurso         bigint                        not null
        references public.tb_percursos
            on delete restrict,
    id_percurso_arquivo bigint
                                                      references public.tb_percurso_arquivos
                                                          on delete set null,
    id_usuario          bigint                        not null,
    acao                varchar(50)                   not null,
    dados               jsonb     default '{}'::jsonb not null,
    endereco_ip         varchar(64),
    criado_em           timestamp default now()       not null
);

alter table public.tb_percurso_historico
    owner to runner_dba;

grant select, usage on sequence public.tb_percurso_historico_id_historico_seq to runner;

create index tb_percurso_historico_percurso_idx
    on public.tb_percurso_historico (id_percurso asc, criado_em desc);

grant insert, select on public.tb_percurso_historico to runner;

create table public.tb_evento_percursos_gpx
(
    id_evento_percurso_gpx bigserial
        primary key,
    id_evento              integer                                not null
        references public.tb_evento_corridas
            on delete cascade,
    id_percurso            bigint                                 not null
        references public.tb_percursos
            on delete cascade,
    id_usuario_criador     bigint                                 not null,
    criado_em              timestamp with time zone default now() not null,
    id_evento_percurso     integer
        constraint fk_evento_percursos_gpx_modalidade
            references public.tb_evento_corridas_percursos
            on update cascade on delete cascade
);

alter table public.tb_evento_percursos_gpx
    owner to runner_dba;

grant select, usage on sequence public.tb_evento_percursos_gpx_id_evento_percurso_gpx_seq to runner;

create index tb_evento_percursos_gpx_percurso_idx
    on public.tb_evento_percursos_gpx (id_percurso, id_evento);

create index tb_evento_percursos_gpx_evento_idx
    on public.tb_evento_percursos_gpx (id_evento, id_percurso);

create unique index tb_evento_percursos_gpx_manual_uq
    on public.tb_evento_percursos_gpx (id_evento, id_percurso)
    where (id_evento_percurso IS NULL);

create unique index tb_evento_percursos_gpx_modalidade_uq
    on public.tb_evento_percursos_gpx (id_evento_percurso)
    where (id_evento_percurso IS NOT NULL);

create index tb_evento_percursos_gpx_modalidade_idx
    on public.tb_evento_percursos_gpx (id_evento_percurso, id_percurso);

grant delete, insert, select, update on public.tb_evento_percursos_gpx to runner;

create table public.tb_percurso_migracoes_strava
(
    id_migracao            bigserial
        primary key,
    id_evento_percurso     integer                                                        not null
        constraint tb_percurso_migracoes_strava_modalidade_uq
            unique
        references public.tb_evento_corridas_percursos
            on update cascade on delete restrict,
    id_evento              integer                                                        not null
        references public.tb_evento_corridas
            on update cascade on delete restrict,
    strava_route_id        varchar(128)                                                   not null,
    strava_url             varchar(512)                                                   not null,
    status                 varchar(24)              default 'pendente'::character varying not null
        constraint tb_percurso_migracoes_strava_status_chk
            check ((status)::text = ANY
                   ((ARRAY ['pendente'::character varying, 'processando'::character varying, 'validado'::character varying, 'migrado'::character varying, 'reutilizado'::character varying, 'revisao'::character varying, 'erro'::character varying, 'ignorado'::character varying])::text[])),
    id_percurso            bigint
                                                                                          references public.tb_percursos
                                                                                              on delete set null,
    id_percurso_arquivo    bigint
                                                                                          references public.tb_percurso_arquivos
                                                                                              on delete set null,
    sha256                 char(64),
    distancia_gpx_m        numeric(14, 2),
    tentativas             integer                  default 0                             not null
        constraint tb_percurso_migracoes_strava_tentativas_chk
            check (tentativas >= 0),
    ultimo_http_status     integer,
    mensagem               text,
    dados                  jsonb                    default '{}'::jsonb                   not null,
    id_usuario_ultima_acao bigint,
    data_criacao           timestamp with time zone default now()                         not null,
    data_atualizacao       timestamp with time zone default now()                         not null,
    data_ultima_tentativa  timestamp with time zone,
    data_conclusao         timestamp with time zone
);

alter table public.tb_percurso_migracoes_strava
    owner to runner_dba;

grant select, usage on sequence public.tb_percurso_migracoes_strava_id_migracao_seq to runner;

create index tb_percurso_migracoes_strava_status_idx
    on public.tb_percurso_migracoes_strava (status, data_atualizacao, id_evento_percurso);

create index tb_percurso_migracoes_strava_rota_idx
    on public.tb_percurso_migracoes_strava (strava_route_id);

create index tb_percurso_migracoes_strava_percurso_idx
    on public.tb_percurso_migracoes_strava (id_percurso, id_evento_percurso);

grant delete, insert, select, update on public.tb_percurso_migracoes_strava to runner;

