);

alter table liverunners.credit_transactions
    owner to liverunners_dba;

create index credit_transactions_org_idx
    on liverunners.credit_transactions (organization_id asc, created_at desc);

create index credit_transactions_race_idx
    on liverunners.credit_transactions (race_id)
