create table public.tb_push_delivery_queue
(
    id_push_delivery     bigserial
        primary key,
    id_notifica          integer                                          not null
        references public.tb_notifica
            on delete cascade,
    id_usuario           integer                                          not null,
    id_push_subscription bigint                                           not null
        references public.tb_push_subscription
            on delete cascade,
    ambiente             varchar(16)                                      not null,
    categoria            varchar(24),
    urgencia             varchar(16) default 'normal'::character varying  not null,
    ttl_seconds          integer     default 300                          not null,
    payload              jsonb                                            not null,
    status               varchar(20) default 'pending'::character varying not null
        constraint ck_push_delivery_status
            check ((status)::text = ANY
                   ((ARRAY ['pending'::character varying, 'processing'::character varying, 'accepted'::character varying, 'retry'::character varying, 'failed'::character varying, 'expired'::character varying, 'cancelled'::character varying])::text[])),
    attempts             integer     default 0                            not null,
    max_attempts         integer     default 5                            not null,
    available_at         timestamp   default now()                        not null,
    locked_at            timestamp,
    locked_by            varchar(80),
    accepted_at          timestamp,
    expired_at           timestamp,
    last_http_status     integer,
    last_error           text,
    created_at           timestamp   default now()                        not null,
    updated_at           timestamp   default now()                        not null,
    constraint uq_push_delivery_notification_subscription
        unique (id_notifica, id_push_subscription)
);

comment on table public.tb_push_delivery_queue is 'Fila durável de entregas Web Push, uma linha por notificação e dispositivo.';

alter table public.tb_push_delivery_queue
    owner to runner_dba;

create index idx_push_delivery_claim
    on public.tb_push_delivery_queue (available_at, id_push_delivery)
    where ((status)::text = ANY ((ARRAY ['pending'::character varying, 'retry'::character varying])::text[]));

create index idx_push_delivery_notification
    on public.tb_push_delivery_queue (id_notifica, status);

create index idx_push_delivery_subscription
    on public.tb_push_delivery_queue (id_push_subscription asc, created_at desc);

create table public.tb_push_delivery_attempt
(
    id_push_delivery_attempt bigserial
        primary key,
    id_push_delivery         bigint                  not null
        references public.tb_push_delivery_queue
            on delete cascade,
    attempt_number           integer                 not null,
    started_at               timestamp default now() not null,
    finished_at              timestamp,
    duration_ms              integer,
    http_status              integer,
    provider                 varchar(80),
    accepted                 boolean   default false not null,
    permanent_failure        boolean   default false not null,
    retry_after_seconds      integer,
    error_message            text,
    response_headers         jsonb,
    created_at               timestamp default now() not null
);

comment on table public.tb_push_delivery_attempt is 'Histórico de tentativas HTTP realizadas contra os provedores Web Push.';

alter table public.tb_push_delivery_attempt
    owner to runner_dba;

create index idx_push_delivery_attempt_delivery
    on public.tb_push_delivery_attempt (id_push_delivery asc, attempt_number desc);

create table public.tb_push_notification_event
(
    id_push_notification_event bigserial
        primary key,
    id_push_delivery           bigint
                                                       references public.tb_push_delivery_queue
                                                           on delete set null,
    id_notifica                integer
                                                       references public.tb_notifica
                                                           on delete set null,
    id_usuario                 integer,
    id_push_subscription       bigint
                                                       references public.tb_push_subscription
                                                           on delete set null,
    event_type                 varchar(24)             not null
        constraint ck_push_notification_event_type
            check ((event_type)::text = ANY
                   ((ARRAY ['displayed'::character varying, 'clicked'::character varying, 'dismissed'::character varying, 'subscription_refreshed'::character varying])::text[])),
    event_at                   timestamp default now() not null,
    metadata                   jsonb
);

comment on table public.tb_push_notification_event is 'Eventos observáveis no cliente; aceite do provedor não equivale a visualização.';

alter table public.tb_push_notification_event
    owner to runner_dba;

create index idx_push_notification_event_notification
    on public.tb_push_notification_event (id_notifica asc, event_type asc, event_at desc);

create table public.tb_cron_job_notification_recipients
(
    id_cron_job           bigint                  not null
        references public.tb_cron_jobs
