create view mercado.v_top100_pessoas
            (id_entidade, nome, power_index_0_100, poder_estrutural_0_10, impacto_econ_0_10, influencia_dir_0_10,
             impacto_sist_0_10, status_verificacao)
as
SELECT e.id_entidade,
    e.nome,
    es.power_index_0_100,
    es.poder_estrutural_0_10,
    es.impacto_econ_0_10,
    es.influencia_dir_0_10,
    es.impacto_sist_0_10,
    es.status_verificacao
   FROM mercado.entidade e
     JOIN LATERAL ( SELECT es_1.id_run,
            es_1.id_entidade,
            es_1.poder_estrutural_0_10,
            es_1.impacto_econ_0_10,
            es_1.influencia_dir_0_10,
            es_1.impacto_sist_0_10,
            es_1.power_index_0_100,
            es_1.status_verificacao,
            es_1.racional
           FROM mercado.entidade_score es_1
             JOIN mercado.scoring_run r ON r.id_run = es_1.id_run
          WHERE es_1.id_entidade = e.id_entidade
          ORDER BY r.created_at DESC
         LIMIT 1) es ON true
  WHERE e.entity_type = 'pessoa'::mercado.entity_type_enum
  ORDER BY es.power_index_0_100 DESC NULLS LAST, e.nome
 LIMIT 100;

alter table mercado.v_top100_pessoas
    owner to runner_dba;

create view mercado.v_master_flat
            (id_entidade, entity_type, nome, uf, cidade, instagram_handle, linkedin_url, site_url, power_index_0_100,
             poder_estrutural_0_10, impacto_econ_0_10, influencia_dir_0_10, impacto_sist_0_10, status_verificacao,
             tipo_organizacao, categoria, subcategoria, categoria_principal, subcategoria_detalhe, bloco_mercado, tags,
             arquetipo_forbes, pilar_dominante_raw, camada_estrutural, rodada_entrada, evidencias_top)
as
SELECT e.id_entidade,
    e.entity_type,
    e.nome,
    e.uf,
    e.cidade,
    e.instagram_handle,
    e.linkedin_url,
    e.site_url,
    es.power_index_0_100,
    es.poder_estrutural_0_10,
    es.impacto_econ_0_10,
    es.influencia_dir_0_10,
    es.impacto_sist_0_10,
    es.status_verificacao,
    o.tipo_organizacao,
    c.categoria,
    c.subcategoria,
    c.categoria_principal,
    c.subcategoria_detalhe,
    c.bloco_mercado,
    c.tags,
    c.arquetipo_forbes,
    c.pilar_dominante_raw,
    c.camada_estrutural,
    c.rodada_entrada,
    ( SELECT array_agg(ev.url ORDER BY ev.confianca_0_1 DESC, ev.id_evidencia DESC) AS array_agg
           FROM mercado.evidencia ev
          WHERE ev.id_entidade = e.id_entidade
         LIMIT 10) AS evidencias_top
   FROM mercado.entidade e
     LEFT JOIN mercado.organizacao o ON o.id_entidade = e.id_entidade
     LEFT JOIN mercado.entidade_classificacao c ON c.id_entidade = e.id_entidade
     LEFT JOIN LATERAL ( SELECT es_1.id_run,
            es_1.id_entidade,
            es_1.poder_estrutural_0_10,
            es_1.impacto_econ_0_10,
            es_1.influencia_dir_0_10,
            es_1.impacto_sist_0_10,
            es_1.power_index_0_100,
            es_1.status_verificacao,
            es_1.racional
           FROM mercado.entidade_score es_1
             JOIN mercado.scoring_run r ON r.id_run = es_1.id_run
          WHERE es_1.id_entidade = e.id_entidade
          ORDER BY r.created_at DESC
         LIMIT 1) es ON true;

alter table mercado.v_master_flat
    owner to runner_dba;

create view mercado.v_grafo_edges
            (id_grafo_run, id_rel, id_origem, origem_nome, origem_tipo, id_destino, destino_nome, destino_tipo,
             rel_tipo, direcao, peso_0_1, confianca_0_1, racional, fonte_tipo, fonte_url, fonte_data, created_at)
as
SELECT r.id_grafo_run,
    r.id_rel,
    r.id_origem,
    eo.nome AS origem_nome,
    eo.entity_type::text AS origem_tipo,
    r.id_destino,
    ed.nome AS destino_nome,
    ed.entity_type::text AS destino_tipo,
    r.tipo AS rel_tipo,
    r.direcao,
    r.peso_0_1,
    r.confianca_0_1,
    r.racional,
    r.fonte_tipo,
    r.fonte_url,
    r.fonte_data,
    r.created_at
   FROM mercado.relacionamento r
     JOIN mercado.entidade eo ON eo.id_entidade = r.id_origem
     JOIN mercado.entidade ed ON ed.id_entidade = r.id_destino;

alter table mercado.v_grafo_edges
    owner to runner_dba;

create view mercado.v_grafo_nodes
            (id_entidade, nome, entity_type, tipo_organizacao, bloco_mercado, categoria_principal, subcategoria_detalhe,
             tags, power_index_0_100, poder_estrutural_0_10, impacto_econ_0_10, influencia_dir_0_10, impacto_sist_0_10,
             status_verificacao)
as
SELECT e.id_entidade,
    e.nome,
    e.entity_type::text AS entity_type,
    o.tipo_organizacao,
    c.bloco_mercado,
    c.categoria_principal,
    c.subcategoria_detalhe,
    c.tags,
    es.power_index_0_100,
    es.poder_estrutural_0_10,
    es.impacto_econ_0_10,
    es.influencia_dir_0_10,
    es.impacto_sist_0_10,
    es.status_verificacao::text AS status_verificacao
   FROM mercado.entidade e
     LEFT JOIN mercado.organizacao o ON o.id_entidade = e.id_entidade
     LEFT JOIN mercado.entidade_classificacao c ON c.id_entidade = e.id_entidade
     LEFT JOIN LATERAL ( SELECT es_1.id_run,
            es_1.id_entidade,
            es_1.poder_estrutural_0_10,
            es_1.impacto_econ_0_10,
            es_1.influencia_dir_0_10,
            es_1.impacto_sist_0_10,
            es_1.power_index_0_100,
            es_1.status_verificacao,
            es_1.racional
           FROM mercado.entidade_score es_1
             JOIN mercado.scoring_run sr ON sr.id_run = es_1.id_run
          WHERE es_1.id_entidade = e.id_entidade
          ORDER BY sr.created_at DESC
         LIMIT 1) es ON true;

