create view mercado.v_grafo_metricas
            (id_grafo_run, id_entidade, nome, entity_type, indegree, outdegree, indegree_peso, outdegree_peso) as
SELECT r.id_grafo_run,
    e.id_entidade,
    e.nome,
    e.entity_type::text AS entity_type,
    sum(
        CASE
            WHEN rel.id_destino = e.id_entidade THEN 1
            ELSE 0
        END) AS indegree,
    sum(
        CASE
            WHEN rel.id_origem = e.id_entidade THEN 1
            ELSE 0
        END) AS outdegree,
    sum(
        CASE
            WHEN rel.id_destino = e.id_entidade THEN rel.peso_0_1
            ELSE 0::numeric
        END) AS indegree_peso,
    sum(
        CASE
            WHEN rel.id_origem = e.id_entidade THEN rel.peso_0_1
            ELSE 0::numeric
        END) AS outdegree_peso
   FROM mercado.grafo_run r
     JOIN mercado.entidade e ON true
     LEFT JOIN mercado.relacionamento rel ON rel.id_grafo_run = r.id_grafo_run AND (rel.id_origem = e.id_entidade OR rel.id_destino = e.id_entidade)
  GROUP BY r.id_grafo_run, e.id_entidade, e.nome, (e.entity_type::text);

alter table mercado.v_grafo_metricas
    owner to runner_dba;

