create view crm.vw_crm_participacoes
            (id_crm_participacao, id_crm_pessoa, id_crm_pedido, id_crm_evento_versao, id_crm_evento_serie, nome_serie,
             fonte_evento, fonte, id_parceiro, cod_evento_externo, nome_evento, ano_evento, data_evento, id_evento,
             numero_inscricao, numero_pedido, protocolo, numero_peito, percurso, percurso_label, modalidade, categoria,
             status_inscricao, status_pedido, status_participacao, data_pedido, data_pagamento, origem, campanha, cupom,
             valor_unitario, valor_repasse, camiseta, assessoria, pace_declarado, instagram, telefone_whatsapp,
             interesse_viagem, nome, nome_norm, email, email_norm, documento, documento_norm, telefone, telefone_norm,
             data_nascimento, sexo, cidade, estado, pais, id_usuario, match_usuario_status, match_usuario_confianca,
             usuario_nome, usuario_email, id_resultado, correu, concluinte, status_resultado, tempo_total,
             pace_resultado, match_resultado_status, match_resultado_confianca, lead_score, lead_score_componentes,
             data_criacao, data_atualizacao)
as
SELECT part.id_crm_participacao,
    part.id_crm_pessoa,
    part.id_crm_pedido,
    part.id_crm_evento_versao,
    serie.id_crm_evento_serie,
    serie.nome_serie,
    vers.fonte AS fonte_evento,
    part.fonte,
    part.id_parceiro,
    part.cod_evento_externo,
    COALESCE(evt.nome_evento, part.nome_evento_externo, vers.nome_evento_externo) AS nome_evento,
    part.ano_evento,
    COALESCE(evt.data_inicial, part.data_evento, vers.data_evento) AS data_evento,
    part.id_evento,
    part.numero_inscricao,
    part.numero_pedido,
    part.protocolo,
    part.numero_peito,
    part.percurso,
    part.percurso_label,
    part.modalidade,
    part.categoria,
    part.status_inscricao,
    COALESCE(part.status_pedido, ped.status_pedido) AS status_pedido,
    part.status_participacao,
    COALESCE(part.data_pedido, ped.data_pedido) AS data_pedido,
    COALESCE(part.data_pagamento, ped.data_pagamento) AS data_pagamento,
    part.origem,
    part.campanha,
    part.cupom,
    part.valor_unitario,
    part.valor_repasse,
    part.camiseta,
    part.assessoria,
    part.pace_declarado,
    part.instagram,
    part.telefone_whatsapp,
    part.interesse_viagem,
    pessoa.nome,
    pessoa.nome_norm,
    pessoa.email,
    pessoa.email_norm,
    pessoa.documento,
    pessoa.documento_norm,
    pessoa.telefone,
    pessoa.telefone_norm,
    pessoa.data_nascimento,
    pessoa.sexo,
    pessoa.cidade,
    pessoa.estado,
    pessoa.pais,
    pessoa.id_usuario,
    pessoa.match_usuario_status,
    pessoa.match_usuario_confianca,
    usr.name AS usuario_nome,
    usr.email AS usuario_email,
    part.id_resultado,
    COALESCE(part.correu, res.id_resultado IS NOT NULL) AS correu,
    COALESCE(part.concluinte, res.concluinte) AS concluinte,
    COALESCE(part.status_resultado, res.status_final) AS status_resultado,
    COALESCE(part.tempo_total, res.tempo_total) AS tempo_total,
    COALESCE(part.pace_resultado, res.pace) AS pace_resultado,
    part.match_resultado_status,
    part.match_resultado_confianca,
    part.lead_score,
    part.lead_score_componentes,
    part.data_criacao,
    part.data_atualizacao
   FROM crm.tb_crm_participacoes part
     JOIN crm.tb_crm_pessoas pessoa ON pessoa.id_crm_pessoa = part.id_crm_pessoa
     LEFT JOIN crm.tb_crm_pedidos ped ON ped.id_crm_pedido = part.id_crm_pedido
     LEFT JOIN crm.tb_crm_evento_versoes vers ON vers.id_crm_evento_versao = part.id_crm_evento_versao
     LEFT JOIN crm.tb_crm_evento_series serie ON serie.id_crm_evento_serie = vers.id_crm_evento_serie
     LEFT JOIN tb_evento_corridas evt ON evt.id_evento = part.id_evento
     LEFT JOIN tb_usuarios usr ON usr.id = pessoa.id_usuario
     LEFT JOIN tb_resultados res ON res.id_resultado = part.id_resultado;

alter table crm.vw_crm_participacoes
    owner to runner_dba;

grant select on crm.vw_crm_participacoes to runner;

create view crm.vw_crm_leads
            (id_crm_pessoa, nome, email, documento, telefone, cidade, estado, id_usuario, match_usuario_status,
             total_participacoes, total_versoes, ultima_data_evento, ultima_data_pedido, total_pagos, total_corriu,
             total_concluiu, percurso_preferido, lead_score_maximo, lead_score_medio)
as
SELECT pessoa.id_crm_pessoa,
    pessoa.nome,
    pessoa.email,
    pessoa.documento,
    pessoa.telefone,
    pessoa.cidade,
    pessoa.estado,
    pessoa.id_usuario,
    pessoa.match_usuario_status,
    count(part.id_crm_participacao)::integer AS total_participacoes,
    count(DISTINCT part.id_crm_evento_versao)::integer AS total_versoes,
    max(COALESCE(part.data_evento, vers.data_evento)) AS ultima_data_evento,
    max(part.data_pedido) AS ultima_data_pedido,
    count(*) FILTER (WHERE COALESCE(part.status_pedido, ''::character varying)::text ~~* 'Pago'::text)::integer AS total_pagos,
    count(*) FILTER (WHERE COALESCE(part.correu, false) = true)::integer AS total_corriu,
    count(*) FILTER (WHERE COALESCE(part.concluinte, false) = true)::integer AS total_concluiu,
    ( SELECT pref.percurso
           FROM crm.tb_crm_participacoes pref
          WHERE pref.id_crm_pessoa = pessoa.id_crm_pessoa AND pref.percurso IS NOT NULL
          GROUP BY pref.percurso
          ORDER BY (count(*)) DESC, (max(pref.data_pedido)) DESC NULLS LAST, pref.percurso
         LIMIT 1) AS percurso_preferido,
    max(part.lead_score) AS lead_score_maximo,
    avg(part.lead_score) AS lead_score_medio
   FROM crm.tb_crm_pessoas pessoa
     LEFT JOIN crm.tb_crm_participacoes part ON part.id_crm_pessoa = pessoa.id_crm_pessoa
     LEFT JOIN crm.tb_crm_evento_versoes vers ON vers.id_crm_evento_versao = part.id_crm_evento_versao
  GROUP BY pessoa.id_crm_pessoa, pessoa.nome, pessoa.email, pessoa.documento, pessoa.telefone, pessoa.cidade, pessoa.estado, pessoa.id_usuario, pessoa.match_usuario_status;

alter table crm.vw_crm_leads
    owner to runner_dba;

grant select on crm.vw_crm_leads to runner;

