create procedure public.atualiza()
    language plpgsql
as
$$
DECLARE
rec_eventos        record;

cur_eventos cursor for
select
    id_evento,
    nome_evento,
    data_inicial,
    data_final,
    categorias
from
    tb_evento_corridas;


BEGIN
    open cur_eventos;
    loop
        fetch cur_eventos into rec_eventos;
        exit when not found;

        call grava_evento_corridas_percursos(rec_eventos.id_evento,rec_eventos.nome_evento,rec_eventos.data_inicial,rec_eventos.data_final,rec_eventos.categorias);

    end loop;

    close cur_eventos;


END
$$;

alter procedure public.atualiza() owner to runner_dba;

