create function news.fn_content_force_hidden_on_insert() returns trigger
    language plpgsql
as
$$
BEGIN
    -- Toda notícia nova precisa passar pela curadoria manual do Business.
    NEW.published := false;
    NEW.editorial_status := 'draft';
    NEW.is_featured := false;
    NEW.published_at := NULL;
    RETURN NEW;
END;
$$;

alter function news.fn_content_force_hidden_on_insert() owner to runner_dba;

